import re

def sim_algo1(F, fs):
    ranges = [[F, F]]
    for f in fs:
        merged = False
        for r in ranges:
            if r[1] + 1 == f:
                r[1] = f
                merged = True
                break
            elif r[0] == f + 1:
                r[0] = f
                merged = True
                break
        if not merged:
            ranges.append([f, f])
    out = []
    for r in ranges:
        out.extend(range(r[0], r[1] + 1))
    return out

with open('pairs.txt') as file:
    for line in file:
        m = re.match(r'(\d+): (\d+),(\d+) -> (.*)', line.strip())
        if m:
            F = int(m.group(1))
            fs = [int(m.group(2)), int(m.group(3))]
            expected = list(map(int, m.group(4).split()))
            if sim_algo1(F, fs) != expected:
                print(f"Failed {F}: {fs} -> Expected {expected}, Got {sim_algo1(F, fs)}")
                break
