def sim_algo2(F, fs):
    ranges = [[F, F]]
    for f in fs:
        # Check if f is contiguous to the LAST range
        last = ranges[-1]
        if last[1] + 1 == f:
            last[1] = f
        # Check if f is contiguous to the FIRST range
        elif ranges[0][0] == f + 1:
