import re

def sim_algo8(F, fs):
    ranges = [[F, F]]
    for f in fs:
        merged = False
        for r in ranges:
            # Append to end of range (always allowed)
            if r[1] + 1 == f:
                r[1] = f
                merged = True
                break
            # Prepend to start of range (only if start == end)
            elif f + 1 == r[0] and r[0] == r[1]:
                r[0] = f
                merged = True
                break
        if not merged:
            ranges.append([f, f])

