def sim_algo10(F, fs):
    ranges = [[F, F]]
    for f in fs:
        merged = False
        r = ranges[0]
        # Append to end of F range
        if r[1] + 1 == f:
            r[1] = f
            merged = True
        # Prepend to start of F range ONLY if length is 1
        elif f + 1 == r[0] and r[0] == r[1]:
            r[0] = f
            merged = True

        if not merged:
            ranges.append([f, f])

    out = []
    for r in ranges:
        out.extend(range(r[0], r[1] + 1))
    return out

with open('pairs.txt') as file:
    for line in file:
        m = re.match(r'(\d+): (\d+),(\d+) -> (.*)', line.strip())
        if m:
            F = int(m.group(1))
            fs = [int(m.group(2)), int(m.group(3))]
            expected = list(map(int, m.group(4).split()))
            if sim_algo10(F, fs) != expected:
                print(f"Failed {F}: {fs} -> Expected {expected}, Got {sim_algo10(F, fs)}")
                break
else:
    print("SUCCESS! ALGO MATCHES PERFECTLY!")
