import re

def sim_algo13(F, fs):
    ranges = [[F, F]]
    for f in fs:
        merged = False
        new_range = [f, f]

        # Try to append to ANY range
        for i in range(len(ranges)):
            if ranges[i][1] + 1 == new_range[0]:
                ranges[i][1] = new_range[1]
                merged = True
                # Cascade merge
                for j in range(len(ranges)):
                    if i != j:
                        # Append to j?
                        if ranges[j][1] + 1 == ranges[i][0]:
                            ranges[j][1] = ranges[i][1]
                            ranges.pop(i)
                            break
                        # Prepend to ranges[0]? (only if len == 1)
                        elif j == 0 and ranges[i][1] + 1 == ranges[0][0] and ranges[0][0] == ranges[0][1]:
                            ranges[0][0] = ranges[i][0]
                            ranges.pop(i)
                            break
                break

        # If not merged, try to prepend to ranges[0] ONLY
        if not merged:
            if new_range[1] + 1 == ranges[0][0] and ranges[0][0] == ranges[0][1]:
                ranges[0][0] = new_range[0]
                merged = True
                # Cascade merge: can ranges[0] now be appended to another range?
                for j in range(1, len(ranges)):
                    if ranges[j][1] + 1 == ranges[0][0]:
                        ranges[j][1] = ranges[0][1]
                        ranges.pop(0)
                        break

        if not merged:
            ranges.append(new_range)

