#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Range {
    start: usize,
    end: usize,
}

fn add_range(ranges: &mut Vec<Range>, new_range: Range, first_f: bool) {
    let mut merged = false;

    // 1. Try to append to ANY range
    for i in 0..ranges.len() {
        if ranges[i].end != usize::MAX && ranges[i].end + 1 == new_range.start {
            ranges[i].end = new_range.end;
            merged = true;

            // Cascade append
            loop {
                let mut cascade_merged = false;
                for j in 0..ranges.len() {
                    if i != j && ranges[j].end != usize::MAX && ranges[j].end + 1 == ranges[i].start {
                        ranges[j].end = ranges[i].end;
                        ranges.remove(i);
                        cascade_merged = true;
                        break;
                    }
                }
                if !cascade_merged {
                    break;
                }
            }
            break;
        }
    }

    if !merged {
        // 2. Try to prepend ONLY to ranges[0] IF it has length 1 AND first_f is true
        if first_f && !ranges.is_empty() {
            let r0 = ranges[0];
            if new_range.end != usize::MAX && new_range.end + 1 == r0.start && r0.start == r0.end {
                ranges[0].start = new_range.start;
                merged = true;

                // Cascade append to ranges[0]
                // (if another range can be appended to it? No, cascade would be ranges[0] appending to another range)
            }
        }
    }

    if !merged {
        // 3. Insert before ranges[0] if first_f and new_range.start < ranges[0].start
        if first_f && !ranges.is_empty() && new_range.start < ranges[0].start {
            ranges.insert(0, new_range);
        } else {
            ranges.push(new_range);
        }
    }
}

fn main() {
    let mut ranges = vec![Range { start: 3, end: 3 }];
    // f = 1,4 -> first_f for 1
    add_range(&mut ranges, Range { start: 1, end: 1 }, true);
    add_range(&mut ranges, Range { start: 4, end: 4 }, false);
    println!("{:?}", ranges);
}
