    #[arg(short = 'f', long = "fields", help = "Fields to keep in the output")]
    fields: Option<String>,

    #[arg(short = 'e', long = "exclude", help = "Fields to exclude from the output")]
    exclude: Option<String>,

    #[arg(short = 'E', long = "exclude-header", action = ArgAction::Append, help = "Headers to exclude from the output")]
    exclude_header: Vec<String>,

    #[arg(short = 'F', long = "header-field", action = ArgAction::Append, help = "A string literal or regex to select headers")]
    header_field: Vec<String>,

    #[arg(short = 'r', long = "header-is-regex", help = "Treat header fields as regex")]
    header_is_regex: bool,

    #[arg(short = 'z', long = "try-decompress", help = "Try to decompress based on file extension")]
    try_decompress: bool,

    #[arg(short = 'Z', long = "try-compress", help = "Try to gzip compress the output")]
    try_compress: bool,

    #[arg(short = 't', long = "compression-threads", default_value_t = 4, help = "Threads to use for compression")]
    compression_threads: usize,

    #[arg(short = 'l', long = "compression-level", default_value_t = 6, help = "Compression level")]
    compression_level: u32,

    #[arg(long = "no-mmap", help = "Disallow mmap")]
    no_mmap: bool,

    #[arg(long = "crlf", help = "Support CRLF newlines")]
    crlf: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FieldRange {
    start: usize,
    end: usize,
}

fn parse_ranges(s: &str) -> Vec<FieldRange> {
    let mut res = Vec::new();
    for part in s.split(',') {
        let part = part.trim();
        if part.is_empty() { continue; }
        if part.starts_with('-') {
            let end: usize = part[1..].parse().unwrap();
            res.push(FieldRange { start: 1, end });
        } else if part.ends_with('-') {
            let start: usize = part[..part.len()-1].parse().unwrap();
            res.push(FieldRange { start, end: usize::MAX });
        } else if part.contains('-') {
            let mut parts = part.split('-');
            let start: usize = parts.next().unwrap().parse().unwrap();
            let end: usize = parts.next().unwrap().parse().unwrap();
            res.push(FieldRange { start, end });
        } else {
            let val: usize = part.parse().unwrap();
            res.push(FieldRange { start: val, end: val });
        }
    }
    res
}

fn add_range(ranges: &mut Vec<FieldRange>, mut new_range: FieldRange, first_f: bool) {
    if ranges.iter().any(|r| r.start <= new_range.start && new_range.end <= r.end) {
        return;
    }

    let mut merged = false;

    // 1. Try to append to ANY range
    for i in 0..ranges.len() {
        if ranges[i].end != usize::MAX && ranges[i].end + 1 == new_range.start {
            ranges[i].end = new_range.end;
            merged = true;

            // Cascade append
            loop {
                let mut cascade_merged = false;
                for j in 0..ranges.len() {
                    if i != j && j < ranges.len() && i < ranges.len() {
                        if ranges[j].end != usize::MAX && ranges[j].end + 1 == ranges[i].start {
                            let end_val = ranges[i].end;
                            ranges[j].end = end_val;
