fn matches_header(h: &str, p: &str, is_regex: bool) -> bool {
    if is_regex {
        if let Ok(re) = Regex::new(p) {
            re.is_match(h)
        } else {
            false
        }
    } else {
        h == p
    }
}

fn get_reader(path: &PathBuf, try_decompress: bool) -> Box<dyn BufRead> {
    if path.to_str() == Some("-") {
        return Box::new(BufReader::new(io::stdin()));
    }
    let file = File::open(path).expect("Failed to open file");
    if try_decompress {
        if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
            let prog = match ext {
                "gz" => Some("gzip"),
                "bz2" => Some("bzip2"),
                "xz" => Some("xz"),
                "zst" => Some("zstd"),
                _ => None,
            };
            if let Some(p) = prog {
