                    .arg("-cd")
                    .arg(path)
                    .stdout(Stdio::piped())
                    .spawn() 
                {
                    return Box::new(BufReader::new(child.stdout.take().unwrap()));
                }
            }
        }
    }
    Box::new(BufReader::new(file))
}

fn main() {
    let mut args = std::env::args().collect::<Vec<_>>();
    let mut parsed_f = None;
    for (i, arg) in args.iter().enumerate() {
        if arg == "-f" || arg == "--fields" {
            parsed_f = Some(args[i+1].clone());
        } else if arg.starts_with("-f") && arg.len() > 2 {
            parsed_f = Some(arg[2..].to_string());
        }
    }

    let mut cli = Cli::parse();
    if let Some(f) = parsed_f {
        cli.fields = Some(f);
    }

    let out_delim = if !cli.use_input_delim {
        cli.output_delimiter.clone()
    } else if cli.delim_is_literal && cli.output_delimiter == "\t" {
        cli.delimiter.clone()
    } else {
        cli.output_delimiter.clone()
    };

    let inputs = if cli.input.is_empty() {
        vec![PathBuf::from("-")]
    } else {
        cli.input.clone()
    };

    let out_target: Box<dyn Write> = if cli.try_compress {
        if let Some(ref path) = cli.output {
            Box::new(flate2::write::GzEncoder::new(File::create(path).unwrap(), flate2::Compression::new(cli.compression_level)))
        } else {
            Box::new(flate2::write::GzEncoder::new(io::stdout(), flate2::Compression::new(cli.compression_level)))
        }
    } else {
        if let Some(ref path) = cli.output {
            Box::new(BufWriter::new(File::create(path).unwrap()))
        } else {
            Box::new(BufWriter::new(io::stdout()))
        }
    };
    let mut out_target = BufWriter::new(out_target);

    let re_delim = if !cli.delim_is_literal {
        Regex::new(&cli.delimiter).ok()
    } else {
        None
    };

    let mut first_file = true;
    let mut ranges: Vec<FieldRange> = Vec::new();
    let mut exclude_indices: Vec<usize> = Vec::new();
    let mut initialized = false;

    let f_ranges = cli.fields.as_ref().map(|s| parse_ranges(s)).unwrap_or_default();
    let e_ranges = cli.exclude.as_ref().map(|s| parse_ranges(s)).unwrap_or_default();

    for path in inputs {
        let mut reader = get_reader(&path, cli.try_decompress);
        let mut line = String::new();

        while reader.read_line(&mut line).unwrap_or(0) > 0 {
            if cli.crlf && line.ends_with("\r\n") {
                line.truncate(line.len() - 2);
            } else if line.ends_with('\n') {
                line.truncate(line.len() - 1);
            }

            let fields: Vec<&str> = if cli.delim_is_literal {
                line.split(&cli.delimiter).collect()
            } else {
                re_delim.as_ref().unwrap().split(&line).collect()
            };

            let num_cols = fields.len();

            if !initialized {
                // Initialize ranges based on headers
                for h_match in &cli.header_field {
                    for (i, f) in fields.iter().enumerate() {
                        if matches_header(f, h_match, cli.header_is_regex) {
                            ranges.push(FieldRange { start: i + 1, end: i + 1 });
                        }
                    }
                }

                let mut first_f = true;
                for fr in f_ranges.iter() {
                    for c in fr.start..=fr.end.min(num_cols) {
                        add_range(&mut ranges, FieldRange { start: c, end: c }, first_f);
                        first_f = false;
                    }
                }

                // If ranges is still empty, fallback to all? No, if no selection, output nothing.

                // Build exclude indices
                for e_match in &cli.exclude_header {
                    for (i, f) in fields.iter().enumerate() {
                        if matches_header(f, e_match, cli.header_is_regex) {
                            exclude_indices.push(i + 1);
                        }
                    }
                }
                for er in e_ranges.iter() {
                    for c in er.start..=er.end.min(num_cols) {
                        exclude_indices.push(c);
                    }
                }

                initialized = true;
            }

            let mut out_fields = Vec::new();
            for r in &ranges {
                let end = r.end.min(num_cols);
                for c in r.start..=end {
                    if !exclude_indices.contains(&c) && c >= 1 && c <= num_cols {
                        out_fields.push(fields[c - 1]);
                    }
                }
            }

            let out_line = out_fields.join(&out_delim);
            writeln!(out_target, "{}", out_line).unwrap();
            line.clear();
        }
        first_file = false;
    }
}
