            let end: usize = part[1..].parse().unwrap();
            res.push(FieldRange { start: 1, end });
        } else if part.ends_with('-') {
            let start: usize = part[..part.len()-1].parse().unwrap();
            res.push(FieldRange { start, end: usize::MAX });
        } else if part.contains('-') {
            let mut parts = part.split('-');
            let start: usize = parts.next().unwrap().parse().unwrap();
            let end: usize = parts.next().unwrap().parse().unwrap();
            res.push(FieldRange { start, end });
        } else {
            let val: usize = part.parse().unwrap();
            res.push(FieldRange { start: val, end: val });
        }
