    let mut args = std::env::args().collect::<Vec<_>>();
    let mut parsed_f = None;
    for (i, arg) in args.iter().enumerate() {
        if arg == "-f" || arg == "--fields" {
            parsed_f = Some(args[i+1].clone());
        } else if arg.starts_with("-f") && arg.len() > 2 {
