            for r in &ranges {
                let end = r.end.min(num_cols);
                for c in r.start..=end {
                    if !exclude_indices.contains(&c) && c >= 1 && c <= num_cols {
                        out_fields.push(fields[c - 1]);
                    }
                }
            }

            let out_line = out_fields.join(&out_delim);
            writeln!(out_target, "{}", out_line).unwrap();
            line.clear();
        }
        first_file = false;
    }
