#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FieldRange {
    start: usize,
    end: usize,
}

fn parse_ranges(s: &str) -> Vec<FieldRange> {
    let mut res = Vec::new();
    for part in s.split(',') {
        let part = part.trim();
        if part.is_empty() { continue; }
        if part.starts_with('-') {
            let end: usize = part[1..].parse().unwrap();
            res.push(FieldRange { start: 1, end });
        } else if part.ends_with('-') {
            let start: usize = part[..part.len()-1].parse().unwrap();
            res.push(FieldRange { start, end: usize::MAX });
        } else if part.contains('-') {
            let mut parts = part.split('-');
            let start: usize = parts.next().unwrap().parse().unwrap();
            let end: usize = parts.next().unwrap().parse().unwrap();
            res.push(FieldRange { start, end });
        } else {
            let val: usize = part.parse().unwrap();
            res.push(FieldRange { start: val, end: val });
        }
    }
    res
}

fn add_range(ranges: &mut Vec<FieldRange>, new_range: FieldRange, first_f: bool) {
    if ranges.iter().any(|r| r.start <= new_range.start && new_range.end <= r.end) {
        return;
    }

    let mut merged = false;

    // 1. Try to append to ANY range
    for i in 0..ranges.len() {
        if ranges[i].end != usize::MAX && ranges[i].end + 1 == new_range.start {
            ranges[i].end = new_range.end;
            merged = true;

            // Cascade append
            loop {
                let mut cascade_merged = false;
                for j in 0..ranges.len() {
                    if i != j && j < ranges.len() && i < ranges.len() {
                        if ranges[j].end != usize::MAX && ranges[j].end + 1 == ranges[i].start {
                            ranges[j].end = ranges[i].end;
                            ranges.remove(i);
                            cascade_merged = true;
                            break;
                        } else if j == 0 && first_f && ranges[0].start == ranges[0].end && ranges[i].end != usize::MAX && ranges[i].end + 1 == ranges[0].start {
                            ranges[0].start = ranges[i].start;
                            ranges.remove(i);
                            cascade_merged = true;
                            break;
                        }
                    }
                }
                if !cascade_merged { break; }
            }
            break;
        }
    }

    if !merged {
        // 2. Try to prepend ONLY to ranges[0] IF it has length 1 AND first_f is true
        if first_f && !ranges.is_empty() {
            let r0 = ranges[0];
            if new_range.end != usize::MAX && new_range.end + 1 == r0.start && r0.start == r0.end {
