#!/usr/bin/env python3
import sys
import re
import argparse
import gzip
import bz2
import lzma
import subprocess
from typing import List, Tuple

def parse_ranges(s: str) -> List[Tuple[int, float]]:
    if not s:
        return []
    res = []
    for part in s.split(','):
        part = part.strip()
        if not part:
            continue
        if part.startswith('-'):
            end = int(part[1:])
            res.append((1, float(end)))
        elif part.endswith('-'):
            start = int(part[:-1])
            res.append((start, float('inf')))
        elif '-' in part:
            parts = part.split('-')
            res.append((int(parts[0]), float(parts[1])))
        else:
            val = int(part)
            res.append((val, float(val)))
    return res

def add_range(ranges: List[List[float]], new_range: List[float], first_f: bool):
    # Values are written only once
    for r in ranges:
        if r[0] <= new_range[0] and new_range[1] <= r[1]:
            return

    merged = False

    # 1. Try to append to ANY range
    for i in range(len(ranges)):
        if ranges[i][1] != float('inf') and ranges[i][1] + 1 == new_range[0]:
            ranges[i][1] = new_range[1]
            merged = True

            # Cascade append
            while True:
                cascade_merged = False
                for j in range(len(ranges)):
                    if i != j and i < len(ranges) and j < len(ranges):
                        if ranges[j][1] != float('inf') and ranges[j][1] + 1 == ranges[i][0]:
                            ranges[j][1] = ranges[i][1]
                            ranges.pop(i)
                            cascade_merged = True
                            break
                        elif j == 0 and first_f and ranges[0][0] == ranges[0][1] and ranges[i][1] != float('inf') and ranges[i][1] + 1 == ranges[0][0]:
                            ranges[0][0] = ranges[i][0]
                            ranges.pop(i)
                            cascade_merged = True
                            break
                if not cascade_merged:
                    break
            break

    if not merged:
        # 2. Try to prepend ONLY to ranges[0] IF it has length 1 AND first_f is true
        if first_f and len(ranges) > 0:
            r0 = ranges[0]
            if new_range[1] != float('inf') and new_range[1] + 1 == r0[0] and r0[0] == r0[1]:
                ranges[0][0] = new_range[0]
                merged = True

    if not merged:
        # 3. Insert before ranges[0] if first_f and new_range[0] < ranges[0][0]
        if first_f and len(ranges) > 0 and new_range[0] < ranges[0][0]:
            ranges.insert(0, new_range)
        else:
            ranges.append(new_range)

def matches_header(h: str, p: str, is_regex: bool) -> bool:
    if is_regex:
        try:
            return bool(re.search(p, h))
        except:
            return False
    return h == p

def get_reader(path: str, try_decompress: bool):
    if path == "-":
        return sys.stdin
    if try_decompress:
        if path.endswith(".gz"):
            return gzip.open(path, 'rt', encoding='utf-8', errors='replace')
        elif path.endswith(".bz2"):
            return bz2.open(path, 'rt', encoding='utf-8', errors='replace')
        elif path.endswith(".xz"):
            return lzma.open(path, 'rt', encoding='utf-8', errors='replace')
        elif path.endswith(".zst"):
            proc = subprocess.Popen(["zstd", "-cd", path], stdout=subprocess.PIPE, text=True, encoding='utf-8', errors='replace')
            return proc.stdout
    return open(path, 'r', encoding='utf-8', errors='replace')

def main():
    parser = argparse.ArgumentParser(prog='executable', add_help=False)
    parser.add_argument('input', nargs='*', default=['-'])
    parser.add_argument('-o', '--output')
    parser.add_argument('-d', '--delimiter', default=r'\s+')
    parser.add_argument('-L', '--delim-is-literal', action='store_true')
    parser.add_argument('-I', '--use-input-delim', action='store_true')
    parser.add_argument('-D', '--output-delimiter', default='\t')
    parser.add_argument('-f', '--fields')
    parser.add_argument('-e', '--exclude')
    parser.add_argument('-E', '--exclude-header', action='append', default=[])
    parser.add_argument('-F', '--header-field', action='append', default=[])
    parser.add_argument('-r', '--header-is-regex', action='store_true')
    parser.add_argument('-z', '--try-decompress', action='store_true')
    parser.add_argument('-Z', '--try-compress', action='store_true')
    parser.add_argument('-t', '--compression-threads', type=int, default=4)
    parser.add_argument('-l', '--compression-level', type=int, default=6)
    parser.add_argument('--no-mmap', action='store_true')
    parser.add_argument('--crlf', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-V', '--version', action='store_true')

    args_list = []
    i = 1
    while i < len(sys.argv):
