            args_list.append(arg[2:])
        elif arg.startswith('-F') and len(arg) > 2:
            args_list.append('-F')
            args_list.append(arg[2:])
        elif arg.startswith('-e') and len(arg) > 2:
            args_list.append('-e')
            args_list.append(arg[2:])
        elif arg.startswith('-E') and len(arg) > 2:
            args_list.append('-E')
            args_list.append(arg[2:])
        elif arg.startswith('-d') and len(arg) > 2:
            args_list.append('-d')
            args_list.append(arg[2:])
        elif arg.startswith('-D') and len(arg) > 2:
            args_list.append('-D')
            args_list.append(arg[2:])
        else:
            args_list.append(arg)
